"""Product analytics dashboard: conversion statistics over customer sessions."""

_CONVERTED_VALUES = {"1": True, "0": False, "": None}


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    for lineno, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = [f.strip() for f in stripped.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {lineno}: expected 3 fields, got {len(fields)}")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError:
            raise ValueError(f"line {lineno}: day is not an integer: {day!r}") from None
        if flag not in _CONVERTED_VALUES:
            raise ValueError(f"line {lineno}: converted must be 1, 0 or empty, got {flag!r}")
        out.append({"id": id_, "day": day, "converted": _CONVERTED_VALUES[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions, keeping the last one per id. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if e["converted"] is True and start_day <= e["day"] <= end_day:
            counts[e["day"] - start_day] += 1
    return counts
